const crypto = require('crypto');
const secret = $env.WEBHOOK_SECRET || 'lendloop-shared-hmac-secret-key-prod';
const convexUrl = $env.CONVEX_URL || 'http://localhost:3000';

const timestamp = Date.now().toString();
const nonce = crypto.randomUUID();
const payload = ''; // empty for GET

const message = `${timestamp}:${nonce}:${payload}`;
const signature = crypto.createHmac('sha256', secret).update(message).digest('hex');

return [{
  json: {
    url: `${convexUrl}/api/overdue-loans`,
    headers: {
      'X-LendLoop-Signature': `sha256=${signature}`,
      'X-LendLoop-Timestamp': timestamp,
      'X-LendLoop-Nonce': nonce,
      'Accept': 'application/json'
    }
  }
}];

const crypto = require('crypto');
const secret = $env.WEBHOOK_SECRET || 'lendloop-shared-hmac-secret-key-prod';
const convexUrl = $env.CONVEX_URL || 'http://localhost:3000';

const item = $input.first().json;
const today = new Date().toISOString().split('T')[0];

// 1. Format reminder message
const message = `[LendLoop Friendly Reminder] Hi ${item.borrowerName}, the tool '${item.toolName}' was due back on ${item.endDate} (${item.daysOverdue} day(s) overdue). Please return it to ${item.lenderName} as soon as possible. Thank you!`;
console.log(`[Dispatched Overdue Reminder to ${item.borrowerEmail}]:`, message);

// 2. Prepare payload for idempotent write-back
const writeBackPayload = {
  loanId: item.loanId,
  status: 'success',
  reminderDate: today,
  details: `Reminder sent: ${item.daysOverdue} day(s) overdue (attempt #${item.reminderCount + 1})`
};

const rawBody = JSON.stringify(writeBackPayload);
const timestamp = Date.now().toString();
const nonce = crypto.randomUUID();
const messageToSign = `${timestamp}:${nonce}:${rawBody}`;
const signature = crypto.createHmac('sha256', secret).update(messageToSign).digest('hex');

return [{
  json: {
    url: `${convexUrl}/api/loan-reminders`,
    body: writeBackPayload,
    headers: {
      'Content-Type': 'application/json',
      'X-LendLoop-Signature': `sha256=${signature}`,
      'X-LendLoop-Timestamp': timestamp,
      'X-LendLoop-Nonce': nonce
    }
  }
}];
